SELECT id, practice_script->>'version' AS version, md5(practice_script::text) AS huella FROM public.nodes WHERE id IN ('5.6','5.8','5.10','5.12','5.15') ORDER BY id;
SELECT id, md5(concat_ws('|', paso, tipo, canal, procedencia, resumen, cita_cerebro, severidad_default)) AS huella FROM public.reglas WHERE id IN ('consolidation.misma_actitud','consolidation.referido_en_frio','consolidation.rehash','consolidation.salida_seca','consolidation.sigue_vendiendo','consolidation.siguientes_pasos','consolidation.sobre_celebra','objection.air_a_objecion','objection.bala_repetida','objection.cierra_sin_bala','objection.circulo_de_cierre','objection.discutir','objection.fff','objection.rrr','objection.rrr_sin_resume','objection.se_desanima','objection.vacia_el_cargador') ORDER BY id;
SELECT max(version) AS version_cerebro, count(*) AS secciones, md5(string_agg(body, '#' ORDER BY order_index)) AS huella_cerebro FROM public.doctrina WHERE is_active;
SELECT node_id, card_order, md5(coalesce(title,'') || '|' || body) AS huella FROM public.node_cards WHERE (node_id, card_order) IN (('5.7',4),('5.8',2),('5.10',1),('5.10',3)) ORDER BY node_id, card_order;
